  function unescapePdfString(s){let out='';for(let i=0;i<s.length;i++){let c=s[i];if(c!=='\\'){out+=c;continue}c=s[++i]||'';if(c==='n')out+='\n';else if(c==='r')out+='\r';else if(c==='t')out+='\t';else if(c==='b')out+='\b';else if(c==='f')out+='\f';else if(/[0-7]/.test(c)){let oct=c;for(let k=0;k<2&&/[0-7]/.test(s[i+1]||'');k++)oct+=s[++i];out+=String.fromCharCode(parseInt(oct,8))}else if(c==='\n'||c==='\r'){if(c==='\r'&&s[i+1]==='\n')i++}else out+=c}return out}
  function hexText(hex){hex=hex.replace(/\s+/g,'');if(hex.length%2)hex+='0';const b=[];for(let i=0;i<hex.length;i+=2)b.push(parseInt(hex.slice(i,i+2),16)||0);if(b[0]===0xfe&&b[1]===0xff){let out='';for(let i=2;i+1<b.length;i+=2)out+=String.fromCharCode((b[i]<<8)|b[i+1]);return out}return td.decode(new Uint8Array(b))}
  function extractText(content){const out=[];const lit=/\(((?:\\.|[^\\)])*)\)\s*Tj/g;let m;while((m=lit.exec(content))){const s=unescapePdfString(m[1]).trim();if(s)out.push(s)}const hex=/<([0-9A-Fa-f\s]+)>\s*Tj/g;while((m=hex.exec(content))){const s=hexText(m[1]).trim();if(s)out.push(s)}const arr=/\[((?:.|\n)*?)\]\s*TJ/g;while((m=arr.exec(content))){let combined='';const inner=m[1],lr=/\(((?:\\.|[^\\)])*)\)|<([0-9A-Fa-f\s]+)>/g;let q;while((q=lr.exec(inner)))combined+=q[1]!=null?unescapePdfString(q[1]):hexText(q[2]);combined=combined.trim();if(combined)out.push(combined)}return out}
